{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this production plan — maximize total profit (unit price minus raw material cost minus processing cost), maximize total revenue, or minimize total cost?"
  ],
  "rationale": "The response asks for a single policy choice among three mutually exclusive objectives, which constitutes one semantically independent clarification question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are there any demand limits (maximum number of units that can be sold) for each product, or can the factory produce and sell unlimited quantities of each product?"
  ],
  "rationale": "The response asks a single clarification question regarding whether demand limits exist or if quantities are unlimited. Although it presents two options, it requires a single policy decision/answer."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For the processing times in the table (e.g., Product I on A1 = 5), are these hours required per single unit of product, or are they some other measure?"
  ],
  "rationale": "The response contains a single clarification question asking for the definition of the processing time units."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For each product, must the quantity processed on stage A exactly equal the quantity processed on stage B (i.e., every unit that goes through stage A must also go through stage B, with no leftover or in-progress units)?"
  ],
  "rationale": "The response contains a single clarification question asking for a specific policy constraint regarding quantity equality between two stages."
}

{
  "action": "question",
